#include "interrupt_handlers.h"
#include "event_queue.h"
#include "system_data.h"

/* UART受信割り込み */
void UART_RX_IRQHandler(void) {
    uint8_t ch = UART_ReceiveByte(); /* 仮関数 */
    EventQueue_Send(&UartQueue, ch);
    EventFlags.EVT_START_REQ = 1;    /* 必要に応じてフラグ設定 */
}

/* タイマ割り込み（1ms毎） */
void Timer0_IRQHandler(void) {
    static uint32_t tick = 0;
    tick++;
    if (tick >= 1000) {
        tick = 0;
        SystemData.timer_1s++;
    }
}
